import{_ as i,C as r,o,c as u,a3 as t,E as s}from"./chunks/framework.CgYN3nbS.js";const v=JSON.parse('{"title":"Séance 5 — Organiser le rapport et écrire pour le client","description":"","frontmatter":{"title":"Séance 5 — Organiser le rapport et écrire pour le client","aside":false},"headers":[],"relativePath":"modules/01-faisabilite/05-ecrire-pour-le-client.md","filePath":"modules/01-faisabilite/05-ecrire-pour-le-client.md"}'),d={name:"modules/01-faisabilite/05-ecrire-pour-le-client.md"};function p(c,e,g,m,h,b){const a=r("NotesCinqQuestions"),n=r("EcrirePourMelanie"),l=r("ChoisirResume");return o(),u("div",null,[e[0]||(e[0]=t('<h1 id="seance-5-—-organiser-le-rapport-et-ecrire-pour-le-client" tabindex="-1">Séance 5 — Organiser le rapport et écrire pour le client <a class="header-anchor" href="#seance-5-—-organiser-le-rapport-et-ecrire-pour-le-client" aria-label="Permalink to &quot;Séance 5 — Organiser le rapport et écrire pour le client&quot;">​</a></h1><h2 id="objectifs" tabindex="-1">Objectifs <a class="header-anchor" href="#objectifs" aria-label="Permalink to &quot;Objectifs&quot;">​</a></h2><ul><li>Mettre en commun les résultats des essais sur les <strong>cinq questions</strong> et repérer ce qu&#39;il reste à chercher pour le survol.</li><li><strong>Organiser</strong> une section du rapport pour qu&#39;une lectrice pressée trouve l&#39;essentiel : le plus important d&#39;abord, un tableau qui résume, un texte qui explique ce qu&#39;il veut dire pour l&#39;entreprise.</li><li><strong>Écrire pour Mélanie</strong> : éviter le jargon, ou l&#39;expliquer la première fois.</li><li>Choisir ce qui va dans le <strong>résumé</strong> et en écrire une première version.</li></ul><h2 id="deroulement-de-la-seance" tabindex="-1">Déroulement de la séance <a class="header-anchor" href="#deroulement-de-la-seance" aria-label="Permalink to &quot;Déroulement de la séance&quot;">​</a></h2><p>La séance se fait en deux temps : <strong>le retour sur le Lab 04 et toute la matière d&#39;abord</strong>, en grand groupe, puis <strong>le reste de la soirée pour le Lab 05</strong>, en équipe. L&#39;enseignant reste disponible dans la réunion du cours pendant le lab.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Heure</th><th style="text-align:left;">Activité</th></tr></thead><tbody><tr><td style="text-align:left;">18 h 30</td><td style="text-align:left;">Retour en grand groupe sur le Lab 04 : les cinq questions</td></tr><tr><td style="text-align:left;">18 h 50</td><td style="text-align:left;">Retour sur l&#39;activité « Le coût sur trois ans »</td></tr><tr><td style="text-align:left;">19 h 00</td><td style="text-align:left;">Organiser une section du rapport</td></tr><tr><td style="text-align:left;">19 h 10</td><td style="text-align:left;">Activité 1 — Écrire pour Mélanie</td></tr><tr><td style="text-align:left;">19 h 30</td><td style="text-align:left;">Le résumé</td></tr><tr><td style="text-align:left;">19 h 40</td><td style="text-align:left;">Activité 2 — Ce qui va dans le résumé</td></tr><tr><td style="text-align:left;">20 h 00</td><td style="text-align:left;">Les consignes du Lab 05 et ce qu&#39;il y a à faire à la maison</td></tr><tr><td style="text-align:left;">20 h 05</td><td style="text-align:left;">Marge pour les questions</td></tr><tr><td style="text-align:left;">20 h 15</td><td style="text-align:left;">Pause</td></tr><tr><td style="text-align:left;">20 h 30</td><td style="text-align:left;"><a href="./../../labs/lab05-ecrire-pour-melanie">Lab 05 — Écrire pour Mélanie</a>, en équipe, jusqu&#39;à la fin de la soirée</td></tr></tbody></table><p>Le <strong>retour en grand groupe</strong> sur le Lab 05 aura lieu <strong>au début de la séance 6</strong>.</p><hr><h2 id="retour-lab-04" tabindex="-1">Retour sur le Lab 04 : les cinq questions <a class="header-anchor" href="#retour-lab-04" aria-label="Permalink to &quot;Retour sur le Lab 04 : les cinq questions {#retour-lab-04}&quot;">​</a></h2><p>Une équipe par question présente en <strong>2 minutes</strong> : les outils essayés et leur famille, deux constats dont une limite, et ce qui est resté non vérifiable. L&#39;enseignant désigne les équipes au début du retour.</p><p>Pendant les présentations, prenez des notes sur les <strong>quatre questions que vous n&#39;avez pas essayées</strong>. Elles vous donnent des pistes pour votre survol, rien de plus : dans le rapport, chaque information sur ces questions doit venir de <strong>votre propre recherche</strong>, avec vos sources.</p>',11)),s(a),e[1]||(e[1]=t('<hr><h2 id="retour-sur-le-cout-sur-trois-ans" tabindex="-1">Retour sur le coût sur trois ans <a class="header-anchor" href="#retour-sur-le-cout-sur-trois-ans" aria-label="Permalink to &quot;Retour sur le coût sur trois ans&quot;">​</a></h2><p>Ouvrez les réponses de l&#39;<a href="./04-essayer-et-comparer#activite-2">activité 2 de la séance 4</a> que vous avez copiées dans vos notes. On compare les résultats, puis les trois erreurs qui reviennent le plus souvent :</p><ul><li>compter les décharges <strong>par réservation</strong> au lieu de <strong>par participant</strong>;</li><li>compter les frais de mise en place <strong>trois fois</strong>, ou les oublier;</li><li>multiplier le <strong>prix de lancement</strong> par trois ans.</li></ul><p>Vérifiez ensuite la ligne « coût sur trois ans » de votre tableau de comparaison : les mêmes erreurs s&#39;y cachent souvent.</p><hr><h2 id="organiser-une-section-du-rapport" tabindex="-1">Organiser une section du rapport <a class="header-anchor" href="#organiser-une-section-du-rapport" aria-label="Permalink to &quot;Organiser une section du rapport&quot;">​</a></h2><p>Mélanie ne lira pas votre rapport du début à la fin, d&#39;un seul trait. Elle va d&#39;abord lire le <strong>résumé</strong>, puis feuilleter : les <strong>titres</strong>, les <strong>tableaux</strong>, la <strong>première phrase</strong> de chaque section. Le rapport doit donc être compréhensible même lu de cette façon.</p><h3 id="le-plus-important-d-abord" tabindex="-1">Le plus important d&#39;abord <a class="header-anchor" href="#le-plus-important-d-abord" aria-label="Permalink to &quot;Le plus important d&#39;abord&quot;">​</a></h3><p>Un rapport n&#39;est pas un roman : on ne garde pas le dénouement pour la fin. Chaque section commence par une phrase qui dit <strong>ce qu&#39;elle montre</strong>, puis donne les détails.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Ce qu&#39;on écrit souvent</th><th style="text-align:left;">Ce qu&#39;on écrit plutôt</th></tr></thead><tbody><tr><td style="text-align:left;">« Dans cette section, nous allons présenter les outils de réservation que nous avons étudiés. »</td><td style="text-align:left;">« Deux outils de réservation ont été essayés. Les deux gèrent les départs à places limitées; un seul échange les réservations avec Viator. »</td></tr><tr><td style="text-align:left;">La phrase annonce le sujet. Le lecteur ne sait toujours rien.</td><td style="text-align:left;">La phrase donne déjà l&#39;essentiel. Le lecteur pressé peut s&#39;arrêter là.</td></tr></tbody></table><h3 id="le-tableau-de-comparaison-ne-parle-pas-seul" tabindex="-1">Le tableau de comparaison ne parle pas seul <a class="header-anchor" href="#le-tableau-de-comparaison-ne-parle-pas-seul" aria-label="Permalink to &quot;Le tableau de comparaison ne parle pas seul&quot;">​</a></h3><p>Un tableau de comparaison sans texte oblige Mélanie à faire l&#39;analyse elle-même. Le gabarit prévoit donc, pour chaque question de la section 6 :</p><ol><li><strong>Le tableau</strong>, avec la ligne « Source(s) ou essai » remplie.</li><li><strong>Les hypothèses du coût sur trois ans, en note</strong> sous le tableau : la date de lecture des prix, le taux de change, le nombre de participants.</li><li><strong>La sous-section « Avantages, limites et points à vérifier »</strong>, qui dit ce que le tableau veut dire <strong>pour l&#39;entreprise</strong> : deux ou trois constats, sans recommander.</li></ol><div class="bg-slate-50 border border-slate-200 text-slate-800 rounded-lg p-4 mb-5"><strong>Exemple d&#39;avantages et de limites</strong> (outils fictifs)<br> « Les deux outils gèrent les départs à places limitées, comme ceux de la via ferrata (essai E1, annexe A). Ils se distinguent surtout sur deux points. Réservio reçoit les réservations de Viator sans qu&#39;on les recopie, ce qui touche directement les doubles réservations de l&#39;été 2026; PagayePro ne le fait pas. En revanche, Réservio coûterait environ 2 000 $ de plus sur trois ans, et ses tutoriels sont offerts en anglais seulement. » </div><p>Les autres tableaux du rapport (exigences, contraintes, risques) n&#39;ont pas besoin d&#39;un paragraphe chacun : le gabarit dit où va le texte, par exemple la section 4.3 pour les contraintes déterminantes.</p><h3 id="les-renvois" tabindex="-1">Les renvois <a class="header-anchor" href="#les-renvois" aria-label="Permalink to &quot;Les renvois&quot;">​</a></h3><p>Le détail va en annexe; le texte y renvoie. Un constat se termine par l&#39;endroit où on peut le vérifier : « (essai E2, annexe A) », « (section 4.1) », « (Réservio, 2026) ». Le lecteur qui veut la preuve la trouve; celui qui est pressé continue.</p><hr><h2 id="ecrire-pour-melanie" tabindex="-1">Écrire pour Mélanie <a class="header-anchor" href="#ecrire-pour-melanie" aria-label="Permalink to &quot;Écrire pour Mélanie&quot;">​</a></h2><p>Mélanie est « correcte avec Facebook et Excel, pas plus ». Un rapport qu&#39;elle ne comprend pas ne l&#39;aide pas à décider, même s&#39;il est exact.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Le moyen</th><th style="text-align:left;">Exemple</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Dire ce que ça fait</strong> plutôt que nommer la technologie</td><td style="text-align:left;">« l&#39;adresse du site » plutôt que « le DNS »</td></tr><tr><td style="text-align:left;"><strong>Expliquer le terme la première fois</strong>, s&#39;il revient souvent ou si Mélanie le reverra</td><td style="text-align:left;">« Le LCP (le temps que met le contenu principal de la page à s&#39;afficher) est de 4,1 secondes. »</td></tr><tr><td style="text-align:left;"><strong>Partir de la conséquence</strong> pour l&#39;entreprise</td><td style="text-align:left;">« Les réservations de Viator arriveraient directement dans le calendrier, sans être recopiées. »</td></tr><tr><td style="text-align:left;"><strong>Une idée par phrase</strong></td><td style="text-align:left;">Deux phrases de 15 mots se lisent mieux qu&#39;une phrase de 30 mots.</td></tr></tbody></table><div class="bg-yellow-50 border border-yellow-200 text-yellow-900 rounded-lg p-4 mb-5"><strong>Simplifier, ce n&#39;est pas devenir vague</strong><br> « La page est lente » est simple, mais ce n&#39;est plus un constat. Gardez la mesure et la source; changez seulement les mots qui l&#39;entourent : « Sur téléphone, la page met 4,1 secondes à afficher son contenu principal (PageSpeed Insights, 20 octobre 2026). » </div><h3 id="activite-1" tabindex="-1">Activité 1 — Écrire pour Mélanie <a class="header-anchor" href="#activite-1" aria-label="Permalink to &quot;Activité 1 — Écrire pour Mélanie {#activite-1}&quot;">​</a></h3><div class="bg-blue-50 border border-blue-200 text-blue-900 rounded-lg p-4 mb-5"><strong>Consigne (10 min, en équipe, puis retour en grand groupe)</strong><br> Six phrases tirées du brouillon d&#39;une équipe fictive. Les outils sont inventés. <ol class="list-decimal pl-5"><li>Cliquez sur les mots que Mélanie ne comprendrait pas, puis sur « Vérifier ».</li><li>Réécrivez la phrase pour Mélanie <strong>avant</strong> de regarder la réécriture proposée. Gardez les mesures et les faits.</li></ol></div>',25)),s(n),e[2]||(e[2]=t('<p><strong>Ce qu&#39;il faut retenir :</strong> la plupart du temps, on peut <strong>éviter</strong> le terme en disant ce qu&#39;il fait pour l&#39;entreprise. Quand on ne peut pas l&#39;éviter, on l&#39;<strong>explique la première fois</strong>, en quelques mots.</p><hr><h2 id="le-resume" tabindex="-1">Le résumé <a class="header-anchor" href="#le-resume" aria-label="Permalink to &quot;Le résumé&quot;">​</a></h2><p>Le résumé est la <strong>première chose</strong> que Mélanie lira, et peut-être la seule. Il tient en une <strong>demi-page</strong> et se lit sans le reste du rapport.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Il contient</th><th style="text-align:left;">Il ne contient pas</th></tr></thead><tbody><tr><td style="text-align:left;">Ce que le projet demande, en deux ou trois phrases</td><td style="text-align:left;">La table des matières en phrases (« ce rapport présente le contexte, les exigences… »)</td></tr><tr><td style="text-align:left;">Les <strong>trois ou quatre constats</strong> qui pèsent le plus sur la suite du projet</td><td style="text-align:left;">Les mesures de détail des essais, les prix au mois</td></tr><tr><td style="text-align:left;">Ce qui suivra : la proposition technique (évaluation 2), et les points qui restent à vérifier avec le client</td><td style="text-align:left;">Une recommandation, ni même un « nous verrons que la meilleure solution… »</td></tr><tr><td style="text-align:left;"></td><td style="text-align:left;">Un terme technique qui n&#39;est expliqué que plus loin</td></tr></tbody></table><div class="bg-red-50 border border-red-300 text-red-900 rounded-lg p-4 mb-5"><strong>Un résumé qui ne résume pas</strong><br> « Ce rapport présente l&#39;évaluation technique du projet d&#39;Aventure Saint-Maurice. Nous y décrivons d&#39;abord le contexte, puis les exigences, les contraintes et les risques. Nous présentons ensuite les possibilités techniques pour les cinq questions. »<br> Après trois phrases, Mélanie ne sait <strong>rien</strong> de plus sur son projet. </div><p>On l&#39;écrit <strong>en dernier</strong> : on ne peut pas résumer ce qui n&#39;est pas encore écrit. Ce soir, vous en écrirez une <strong>première version</strong>, que vous reprendrez quand le rapport sera complet.</p><h3 id="activite-2" tabindex="-1">Activité 2 — Ce qui va dans le résumé <a class="header-anchor" href="#activite-2" aria-label="Permalink to &quot;Activité 2 — Ce qui va dans le résumé {#activite-2}&quot;">​</a></h3><div class="bg-blue-50 border border-blue-200 text-blue-900 rounded-lg p-4 mb-5"><strong>Consigne (10 min, en équipe, puis retour en grand groupe)</strong><br> Une équipe fictive a terminé son rapport. Voici dix phrases tirées de ses sections 2 à 7. Choisissez les <strong>quatre</strong> qui ont leur place dans le résumé, puis cliquez sur « Vérifier ». Lisez ensuite le résumé proposé : remarquez son ordre. </div>',9)),s(l),e[3]||(e[3]=t('<p><strong>Ce qu&#39;il faut retenir :</strong> un constat va dans le résumé s&#39;il <strong>change quelque chose pour la suite du projet</strong> : le budget, le délai, un choix à faire, un risque à régler. Les mesures qui l&#39;appuient restent dans le rapport.</p><hr><h2 id="a-faire-maintenant" tabindex="-1">À faire maintenant <a class="header-anchor" href="#a-faire-maintenant" aria-label="Permalink to &quot;À faire maintenant&quot;">​</a></h2><p><a href="./../../labs/lab05-ecrire-pour-melanie">Lab 05 — Écrire pour Mélanie</a>, en équipe, jusqu&#39;à la fin de la soirée. Avant de partir, déposez votre brouillon; il se termine à la maison.</p><hr><h2 id="a-faire-a-la-maison" tabindex="-1">À faire à la maison <a class="header-anchor" href="#a-faire-a-la-maison" aria-label="Permalink to &quot;À faire à la maison {#a-faire-a-la-maison}&quot;">​</a></h2><div class="bg-yellow-50 border border-yellow-200 text-yellow-900 rounded-lg p-4 mb-5"><strong>La remise approche : 11 novembre, 18 h 30</strong><br> La séance 6 est un <strong>atelier de révision</strong>. Pour qu&#39;elle vous serve, le rapport doit être <strong>complet</strong>, même imparfait : chaque section a du contenu, et il ne reste que la relecture à faire. </div><ul><li><strong>Terminer le survol des quatre autres questions</strong> : pour chacune, le besoin en quelques lignes, deux outils dans un tableau court avec la page de prix datée et le coût sur trois ans, et les points qu&#39;un essai devrait vérifier. Vos notes du retour en grand groupe donnent des pistes; les sources doivent être les vôtres.</li><li><strong>Mettre au propre les sections 3, 4 et 5</strong> à partir de la fiche du Lab 02, en appliquant ce qu&#39;on a vu ce soir : une phrase d&#39;ouverture qui dit l&#39;essentiel, sans jargon, et les trois contraintes déterminantes expliquées en 4.3.</li><li><strong>Écrire la section 7</strong> : les problèmes à prévoir (vos « non vérifiables » du Lab 04 en font partie) et au moins huit questions au client, sans jargon.</li><li><strong>Reprendre le résumé</strong> une fois le reste écrit.</li></ul><hr><h2 id="avant-la-seance-6-4-novembre" tabindex="-1">Avant la séance 6 (4 novembre) <a class="header-anchor" href="#avant-la-seance-6-4-novembre" aria-label="Permalink to &quot;Avant la séance 6 (4 novembre)&quot;">​</a></h2><ul class="checklist"><li><label><input type="checkbox"><span class="check-text">Copier vos réponses des activités 1 et 2, et vos notes sur les cinq questions, dans vos notes</span></label></li><li><label><input type="checkbox"><span class="check-text">Déposer le brouillon du Lab 05 et le résumé dans l&#39;équipe Teams du cours</span></label></li><li><label><input type="checkbox"><span class="check-text">Terminer le survol des quatre autres questions, avec vos propres sources</span></label></li><li><label><input type="checkbox"><span class="check-text">Mettre au propre les sections 3, 4 et 5, et écrire la section 7</span></label></li><li><label><input type="checkbox"><span class="check-text">Faire l&#39;annexe A (vos essais) et commencer les annexes B et C</span></label></li><li><label><input type="checkbox"><span class="check-text">Apporter un rapport complet à la séance 6 : on y fait la révision et le français</span></label></li></ul>',11))])}const f=i(d,[["render",p]]);export{v as __pageData,f as default};
